cd /workspace && python3 -c "
# Test all edge cases for do_POST and do_PUT

# --- do_POST edge cases ---

# Case 1: missing title
print('=== POST missing title ===')
title = None
author = 'A'
isbn = '1'
try:
    if not title.strip() or not author.strip() or not isbn.strip():
        print('  would crash (None.strip)')
except AttributeError as e:
    print(f'  CRASH: {e}')

# Case 2: title is empty string
print('=== POST title empty string ===')
title = ''
author = 'A'
isbn = '1'
try:
    if not title.strip() or not author.strip() or not isbn.strip():
        print('  would enter empty check')
except:
    pass

# Case 3: title is valid string
print('=== POST title valid string ===')
title = 'Book'
author = 'Author'
isbn = '123'
try:
    if not title.strip() or not author.strip() or not isbn.strip():
        print('  would crash')
    else:
        print('  passes empty check')
    if not title or not author or not isbn:
        print('  would send missing required field')
    else:
        print('  passes all checks, would create')
except:
    pass

# Case 4: title is non-string type (e.g., number)
print('=== POST title is number ===')
title = 123
author = 'Author'
isbn = '123'
try:
    if not title.strip() or not author.strip() or not isbn.strip():
        print('  would crash (123.strip)')
except AttributeError as e:
    print(f'  CRASH: {e}')
"
